"""Generate the salaried dynamics and income comparisons from validated CSVs."""
import csv
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "replication/salaried_extensions_output"
SECTIONS = ROOT / "Paper/sections"


def read(name):
    with (OUT / (name + ".csv")).open(encoding="utf-8-sig", newline="") as stream:
        return list(csv.DictReader(stream))


endpoints = {
    (r["sample"], r["group"], r["clustering"]): r
    for r in read("endpoint_changes") if r["reference"] == "Solo" and r["size"] == "101+"
}
lines = [
    "% Generated by replication/build_salaried_extensions_tables.py.",
    r"\begin{table}[!htbp]", r"  \centering\small",
    r"  \caption{Changes in the 101+/solo premium in the full and salaried-only samples}",
    r"  \label{tab:salaried-dynamic-comparison}",
    r"  \setlength{\tabcolsep}{5pt}", r"  \begin{tabular}{@{}llrrrrr@{}}", r"    \toprule",
    r"    & & \multicolumn{2}{c}{Premium (\%)} & & \multicolumn{2}{c}{$p$-value of change} \\",
    r"    \cmidrule(lr){3-4}\cmidrule(lr){6-7}",
    r"    Sample & Status & 2008 & 2025 & \shortstack{Change\\(pp)} & \shortstack{Sector-\\department} & Sector \\",
    r"    \midrule",
]
for sample, label in (("All", "All workers"), ("Salaried", "Salaried workers")):
    if sample == "Salaried":
        lines.append(r"    \midrule")
    for index, group in enumerate(("Formal", "Informal")):
        r = endpoints[sample, group, "Sector-department"]
        sector = endpoints[sample, group, "Sector"]
        cells = [label if index == 0 else "", group]
        cells += [f'{float(r[k]):.1f}' for k in ("premium_2008", "premium_2025", "change_pp")]
        cells += [f'{float(r["p.value"]):.3f}', f'{float(sector["p.value"]):.3f}']
        lines.append("    " + " & ".join(cells) + r" \\")
lines += [
    r"    \bottomrule", r"  \end{tabular}", r"  \par\vspace{0.4em}",
    r"  \begin{minipage}{0.97\textwidth}\footnotesize",
    r"  Notes: Equation~(\ref{eq:preferred-dynamics}) is estimated jointly for 2008 and 2025 on each sample. "
    r"Premiums compare 101+ with solo workers of the same formality status. Changes are in percentage points. "
    r"Two-sided tests concern the change in the underlying log-wage contrast, using the indicated clustering.",
    r"  \end{minipage}", r"\end{table}", "",
]
(SECTIONS / "regression_salaried_dynamic_comparison_table.tex").write_text("\n".join(lines), encoding="utf-8", newline="\n")

income = {
    (r["sample"], r["scenario"], r["population"]): r for r in read("income_scenarios")
    if r["support"] == "unrestricted" and r["method"] == "predicted" and r["metric"] == "weekly"
}
workers = {r["sample"]: float(r["workers_2025"]) for r in read("sample_audit")}
scenarios = (
    ("formalize_same_size", "Informal to formal, same size"),
    ("formal_to_101", "Formal to formal 101+"),
    ("informal_to_101", "Informal to informal 101+"),
    ("combined_formal_101", "All workers to formal 101+"),
)
lines = [
    "% Generated by replication/build_salaried_extensions_tables.py.",
    r"\begin{table}[!htbp]", r"  \centering\small",
    r"  \caption{Income scenarios in the full and salaried-only samples, 2025}",
    r"  \label{tab:salaried-income-comparison}",
    r"  \setlength{\tabcolsep}{6pt}",
    r"  \begin{tabular}{@{}>{\raggedright\arraybackslash}p{0.36\textwidth}rrr@{}}",
    r"    \toprule",
    r"    Scenario & \shortstack{Workers\\reassigned\\(millions)} & \shortstack{Reassigned\\mean income\\change (\%)} & \shortstack{Sample total\\income\\change (\%)} \\",
    r"    \midrule",
]
for sample, panel, label in (("All", "A", "All workers"), ("Salaried", "B", "Salaried workers")):
    if sample == "Salaried":
        lines.append(r"    \midrule")
    lines.append(r"    \multicolumn{4}{@{}l}{\textit{" + panel + ". " + label +
                 f' ({workers[sample]/1e6:.2f} million)' + r"}} \\[0.3em]")
    for scenario, label in scenarios:
        r = income[sample, scenario, "all"]
        movers = income[sample, scenario, "movers"]
        cells = [label, f'{float(r["workers_moved"])/1e6:.2f}',
                 f'{float(movers["gain_pct"]):.1f}', f'{float(r["gain_pct"]):.1f}']
        lines.append("    " + " & ".join(cells) + r" \\[0.4em]")
lines += [
    r"    \bottomrule", r"  \end{tabular}", r"  \par\vspace{0.4em}",
    r"  \begin{minipage}{0.97\textwidth}\footnotesize",
    r"  Notes: Equation~(\ref{eq:income-counterfactual}) uses the pooled coefficients from "
    r"Equation~(\ref{eq:main}) re-estimated on each sample. Income is predicted weekly labor income. "
    r"Reassigned means exclude workers already at the destination. Sample totals include all workers "
    r"represented in the corresponding panel, including those not reassigned.",
    r"  \end{minipage}", r"\end{table}", "",
]
(SECTIONS / "income_salaried_comparison_table.tex").write_text("\n".join(lines), encoding="utf-8", newline="\n")
print("Generated salaried dynamics and income comparison tables.")
